-- GUARD 1 — the decision table arrived whole, one row per person, all on one topic.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM mig1925_decisions;
  IF n <> 53 THEN RAISE EXCEPTION 'migration 1925: expected 53 decisions, found %', n; END IF;
  SELECT count(*) INTO n FROM (SELECT DISTINCT politician_id, topic_id FROM mig1925_decisions) s;
  IF n <> 53 THEN RAISE EXCEPTION 'migration 1925: duplicate pairs; % distinct of 53', n; END IF;
  SELECT count(DISTINCT topic_id) INTO n FROM mig1925_decisions;
  IF n <> 1 THEN RAISE EXCEPTION 'migration 1925: expected one topic, found %', n; END IF;
END $$;

-- GUARD 2 — every target must TODAY still sit where the queue measured it. If a chair has moved,
-- this file is operating on a stale picture and must stop rather than overwrite someone's work.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1925_decisions d
   WHERE NOT EXISTS (
     SELECT 1 FROM inform.politician_answers pa
      WHERE pa.politician_id = d.politician_id AND pa.topic_id = d.topic_id
        AND pa.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid AND pa.value = d.value_before);
  IF n <> 0 THEN RAISE EXCEPTION 'migration 1925: % target(s) no longer sit where measured — re-measure', n; END IF;
END $$;

-- GUARD 3 — Heinrich must NOT be in this file. He is the one survivor and the guard says so.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1925_decisions d
    JOIN essentials.politicians p ON p.id = d.politician_id
   WHERE p.full_name = 'Martin Heinrich';
  IF n <> 0 THEN RAISE EXCEPTION 'migration 1925: Heinrich is the kept row and must not be blanked'; END IF;
END $$;

-- GUARD 4 — citations must exist to keep. A blank with no citation is a bare assertion.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1925_decisions d
   WHERE NOT EXISTS (
     SELECT 1 FROM inform.politician_context pc
      WHERE pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
        AND coalesce(cardinality(pc.sources), 0) > 0);
  IF n <> 0 THEN RAISE EXCEPTION 'migration 1925: % target(s) have no citations to keep', n; END IF;
END $$;

UPDATE inform.politician_answers pa
   SET value = 0, updated_at = now()
  FROM mig1925_decisions d
 WHERE pa.politician_id = d.politician_id AND pa.topic_id = d.topic_id
   AND pa.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid;

-- Sources are deliberately NOT touched: the row keeps what it cited, so the research survives.
UPDATE inform.politician_context pc
   SET reasoning = d.reasoning, updated_at = now()
  FROM mig1925_decisions d
 WHERE pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
   AND pc.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid;

-- GUARD 5 — verify the RESULT, not the absence of an error.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM mig1925_decisions d
    JOIN inform.politician_answers pa
      ON pa.politician_id = d.politician_id AND pa.topic_id = d.topic_id
     AND pa.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid AND pa.value = 0;
  IF n <> 53 THEN RAISE EXCEPTION 'migration 1925: expected 53 blanked rows, found %', n; END IF;

  SELECT count(*) INTO n
    FROM mig1925_decisions d
    JOIN inform.politician_context pc
      ON pc.politician_id = d.politician_id AND pc.topic_id = d.topic_id
     AND pc.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid
   WHERE coalesce(cardinality(pc.sources), 0) = 0 OR pc.reasoning NOT LIKE '%Shape:%';
  IF n <> 0 THEN RAISE EXCEPTION 'migration 1925: % blank(s) lost citations or a reason code', n; END IF;

  SELECT count(*) INTO n
    FROM inform.politician_answers pa
    JOIN inform.seasons s ON s.id = pa.season_id AND s.name = 'Season 1'
    JOIN mig1925_decisions d ON d.politician_id = pa.politician_id AND d.topic_id = pa.topic_id
   WHERE pa.updated_at > now() - interval '5 minutes';
  IF n <> 0 THEN RAISE EXCEPTION 'migration 1925: % Season 1 answer(s) moved — Season 1 is closed', n; END IF;
END $$;
